  Notation rs0 := (Zupd (0 + 1) 0 rs0d).
  Notation mB := (hs_tableLog h + 1 - maxW).
  Notation ncells := (Z.to_nat (2 ^ mtl)).
  Notation WB := (x2WB SPA DT W mtl).
  Hypothesis XP : X2PATH mtl h maxW rs0a nz rs0d sorted rv0 rv cells.
  Hypothesis HMTL : 1 <= mtl <= 12.
  Hypothesis HDT : ablk DT (DT + 4 + 4 * 2 ^ mtl).
  Hypothesis DT8 : DT mod 8 = 0.
  Hypothesis HWK : ablk W (W + 8704).
  Hypothesis DJW : DT + 4 + 4 * 2 ^ mtl <= W \/ W + 8704 <= DT.
  Hypothesis DSP : DT + 4 + 4 * 2 ^ mtl <= SPA.
  Hypothesis WSP : W + 8704 <= SPA.
  Hypothesis KSP : KHIGH <= SPA.
  Hypothesis SP47 : SPA + 832 <= 2^47.
  Hypothesis UDT : unpoisoned mb DT (DT + 4 + 4 * 2 ^ mtl).
  Hypothesis ZW : zshadow mb W 8704.
  Hypothesis ZDT : zshadow mb DT 8.
  Hypothesis RDT : rng RNG DT (4 + 4 * 2 ^ mtl).
  Hypothesis RDTs : rng RNG (shad DT) (nshad (4 + 4 * 2 ^ mtl + DT mod 8)).
  Hypothesis RWK : rng RNG W 8704.
  Hypothesis RWKs : rng RNG (shad W) (nshad (8704 + W mod 8)).
  Hypothesis RFR : rng RNG SPA 832.
  Hypothesis LJD : length jdt = Z.to_nat (4 * 2 ^ mtl).
  Hypothesis LSY : length SYj = 256%nat.
  Hypothesis BOT : ATOP + 4096 <= lo.
  Hypothesis LOS : lo <= SPA.
  Hypothesis KFIN : x2kfin SPV SPA gp tp F fc RNG mb DT W FF mtl lo T (hs_ret h) jdt cells Q.

  (* [comment removed for export] *)
  Definition x2pk3 (m : amem) : Prop :=
    rw_cells asegs m (SPA + 16) [C8 (Z_to_bv 64 mtl); C8 (Z_to_bv 64 (hs_ret h))]
    /\ rw_cells asegs m (SPA + 56) [C8 (Z_to_bv 64 (Z.shiftr DT 3 + 2147450880)); C8 (Z_to_bv 64 (mtl * 16777217))]
    /\ (exists j, rw_cells asegs m (SPA + 88) [CB 8 j])
    /\ rw_cells asegs m (SPA + 96) [C8 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))]
    /\ (exists v, rw_cells asegs m (SPA + 104) [C8 v])
    /\ (exists j, rw_cells asegs m (SPA + 152) [CB 8 j]) /\ (exists j, rw_cells asegs m (SPA + 168) [CB 24 j])
    /\ (exists j, rw_cells asegs m (SPA + 264) [CB 24 j]) /\ (exists j, rw_cells asegs m (SPA + 288) [CB 8 j])
    /\ (exists j, rw_cells asegs m (SPA + 296) [CB 272 j]) /\ (exists j, rw_cells asegs m (SPA + 568) [CB 16 j])
    /\ (exists j, rw_cells asegs m (SPA + 616) [CB 8 j]) /\ (exists j, rw_cells asegs m (SPA + 624) [CB 80 j])
    /\ u8arr asegs m DT (le4 (Z_to_bv 64 (mtl * 16777217))) /\ u8arr asegs m (DT + 4) jdt
    /\ u32arr asegs m (W + 676) (map (Z_to_bv 64) rs0) /\ rv_atA m W rv (PRwA (maxW + 1) mB (T - mB + 1) 1)
    /\ u8arr asegs m (W + 736) (BM.omerge SYj sorted).

  Notation WG := [(SPA + 32, SPA + 48); (SPA + 72, SPA + 80); (SPA + 144, SPA + 152); (SPA + 160, SPA + 168);
                  (SPA + 192, SPA + 256); (SPA + 584, SPA + 592)].

  Lemma x2pk3_transport : forall m m', x2pk3 m -> munch WG m m' -> wmono asegs m m' -> x2pk3 m'.
